package com.peiwan.platform.serviceexception;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.peiwan.platform.order.OrderService;import com.peiwan.platform.persistence.entity.*;import com.peiwan.platform.persistence.mapper.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class ServiceExceptionService{
 private final ServiceExceptionRequestMapper requests;private final ServiceMemberTransferMapper transfers;private final ServiceExceptionDataMapper data;private final OrderMemberMapper members;private final FulfillmentMapper fulfillments;private final PlayerMapper players;private final OrderService orders;private final ObjectMapper json;
 public ServiceExceptionService(ServiceExceptionRequestMapper requests,ServiceMemberTransferMapper transfers,ServiceExceptionDataMapper data,OrderMemberMapper members,FulfillmentMapper fulfillments,PlayerMapper players,OrderService orders,ObjectMapper json){this.requests=requests;this.transfers=transfers;this.data=data;this.members=members;this.fulfillments=fulfillments;this.players=players;this.orders=orders;this.json=json;}
 @Transactional public long createByCustomer(long uid,long orderId,Command c){var service=data.lockService(orderId);if(service==null||!Objects.equals(((Number)service.get("customer_id")).longValue(),uid))throw new IllegalArgumentException("订单不存在或不属于当前用户");return create(uid,"CUSTOMER",orderId,c,null,service);}
 @Transactional public long createByPlayer(long uid,long orderId,Command c){var service=data.lockService(orderId);var own=data.activeMemberByUser(orderId,uid);if(service==null||own==null)throw new IllegalArgumentException("订单不存在或不属于当前陪玩师");Long ownMember=((Number)own.get("id")).longValue();if(c.sourceOrderMemberId()!=null&&!Objects.equals(c.sourceOrderMemberId(),ownMember))throw new IllegalArgumentException("陪玩师只能为自己发起转单或炸单申请");return create(uid,"PLAYER",orderId,c,ownMember,service);}
 private long create(long uid,String applicant,long orderId,Command c,Long defaultMember,Map<String,Object> service){if(!"IN_SERVICE".equals(service.get("service_status")))throw new IllegalArgumentException("只有服务中的订单可以申请转单或炸单");if(c==null||!Set.of("TRANSFER","ABORT").contains(c.requestType()))throw new IllegalArgumentException("申请类型无效");if(c.reason()==null||c.reason().isBlank())throw new IllegalArgumentException("请填写申请原因");if(data.openRequestCount(orderId)>0)throw new IllegalArgumentException("该订单已有待处理的异常申请");Long source=c.sourceOrderMemberId()!=null?c.sourceOrderMemberId():defaultMember;if(source==null)throw new IllegalArgumentException("请选择涉及的陪玩成员");var member=data.activeMember(orderId,source);if(member==null)throw new IllegalArgumentException("所选成员不是当前在役成员");Long target=c.targetPlayerId();if("TRANSFER".equals(c.requestType())){if(target==null)throw new IllegalArgumentException("请选择接替陪玩师");long sourcePlayer=((Number)member.get("player_id")).longValue();if(target==sourcePlayer)throw new IllegalArgumentException("不能转单给本人");if(data.historicalMember(orderId,target)>0)throw new IllegalArgumentException("接替陪玩师已经参与过此订单");if(data.eligibleTarget(orderId,target)==0)throw new IllegalArgumentException("接替陪玩师不符合游戏等级或接单容量要求");}else target=null;var r=new ServiceExceptionRequestEntity();r.requestNo=no();r.orderId=orderId;r.requestType=c.requestType();r.sourceOrderMemberId=source;r.targetPlayerId=target;r.applicantType=applicant;r.applicantUserId=uid;r.reason=c.reason().trim();r.proofUrls=write(c.proofUrls());r.requestStatus="PENDING";requests.insert(r);return r.id;}
 public Map<String,Object> list(int current,int size,String status,String type){current=Math.max(1,current);size=Math.min(100,Math.max(1,size));var page=data.requests(new Page<>(current,size),status,type);return Map.of("records",page.getRecords().stream().map(this::view).toList(),"current",current,"size",size,"total",page.getTotal());}
 public List<Map<String,Object>> orderRequests(long orderId){return data.orderRequests(orderId).stream().map(this::view).toList();}
 public List<Map<String,Object>> eligibleTargets(long uid,long orderId,Long sourceMemberId){var service=data.lockService(orderId);if(service==null||!"IN_SERVICE".equals(service.get("service_status")))throw new IllegalArgumentException("只有服务中的订单可以选择接替陪玩师");long customer=((Number)service.get("customer_id")).longValue();var own=data.activeMemberByUser(orderId,uid);if(uid!=customer&&own==null)throw new IllegalArgumentException("无权查看该订单候选人");Long source=sourceMemberId!=null?sourceMemberId:own==null?null:((Number)own.get("id")).longValue();if(source==null||data.activeMember(orderId,source)==null)throw new IllegalArgumentException("请选择当前在役成员");return data.eligibleTargets(orderId);}
 public List<Map<String,Object>> pendingTransfers(long uid){Long player=data.playerId(uid);if(player==null)throw new IllegalArgumentException("当前账号未绑定可用陪玩师");return data.pendingTransfers(player).stream().map(this::view).toList();}
 @Transactional public void review(long id,String action,String remark,long operator){var row=data.lockRequest(id);if(row==null)throw new IllegalArgumentException("异常申请不存在");if(!"PENDING".equals(row.get("request_status")))throw new IllegalArgumentException("只有待审核申请可以处理");if(!Set.of("APPROVE","REJECT").contains(action))throw new IllegalArgumentException("审核动作无效");var r=requests.selectById(id);r.reviewedBy=operator;r.reviewedAt=LocalDateTime.now();r.reviewRemark=remark;r.updatedAt=LocalDateTime.now();if("REJECT".equals(action)){if(remark==null||remark.isBlank())throw new IllegalArgumentException("驳回必须填写原因");r.requestStatus="REJECTED";r.resolvedAt=LocalDateTime.now();requests.updateById(r);return;}if("TRANSFER".equals(r.requestType)){r.requestStatus="WAIT_TARGET";requests.updateById(r);return;}r.requestStatus="APPROVED";r.resolvedAt=LocalDateTime.now();requests.updateById(r);orders.abortApproved(r.orderId,r.id,"炸单申请审核通过："+Objects.toString(remark,r.reason),operator);}
 @Transactional public void respond(long uid,long id,String action){var row=data.lockRequest(id);if(row==null||!"TRANSFER".equals(row.get("request_type"))||!"WAIT_TARGET".equals(row.get("request_status")))throw new IllegalArgumentException("转单邀请不存在或已处理");Long player=data.playerId(uid);if(player==null||!Objects.equals(((Number)row.get("target_player_id")).longValue(),player))throw new IllegalArgumentException("该转单邀请不属于当前陪玩师");var r=requests.selectById(id);if("REJECT".equals(action)){r.requestStatus="TARGET_REJECTED";r.resolvedAt=LocalDateTime.now();r.updatedAt=LocalDateTime.now();requests.updateById(r);return;}if(!"ACCEPT".equals(action))throw new IllegalArgumentException("响应动作无效");var service=data.lockService(r.orderId);if(service==null||!"IN_SERVICE".equals(service.get("service_status")))throw new IllegalArgumentException("订单已不在服务中，无法接受转单");var source=data.activeMember(r.orderId,r.sourceOrderMemberId);if(source==null)throw new IllegalArgumentException("原成员已不在役，无法完成转单");if(data.historicalMember(r.orderId,player)>0)throw new IllegalArgumentException("你已经参与过此订单");if(data.eligibleTarget(r.orderId,player)==0)throw new IllegalArgumentException("当前已不满足接单资格或容量要求");var sourceEntity=members.selectById(r.sourceOrderMemberId);var replacement=new OrderMemberEntity();replacement.orderId=r.orderId;replacement.playerId=player;replacement.memberStatus="IN_SERVICE";replacement.joinSource="TRANSFER";replacement.joinedAt=LocalDateTime.now();replacement.serviceStartedAt=LocalDateTime.now();members.insert(replacement);var f=new FulfillmentEntity();f.orderId=r.orderId;f.orderMemberId=replacement.id;f.playerId=player;f.fulfillmentStatus="IN_SERVICE";fulfillments.insert(f);if(data.transferOut(sourceEntity.id)!=1)throw new IllegalArgumentException("原成员状态已变化");data.transferFulfillment(sourceEntity.id);if(data.activeOrderCount(sourceEntity.playerId)==0){var sourcePlayer=players.selectById(sourceEntity.playerId);if(sourcePlayer!=null){sourcePlayer.workStatus="AVAILABLE";sourcePlayer.updatedAt=LocalDateTime.now();players.updateById(sourcePlayer);}}var link=new ServiceMemberTransferEntity();link.orderId=r.orderId;link.exceptionRequestId=r.id;link.fromOrderMemberId=sourceEntity.id;link.toOrderMemberId=replacement.id;link.transferredAt=LocalDateTime.now();transfers.insert(link);r.replacementOrderMemberId=replacement.id;r.requestStatus="RESOLVED";r.resolvedAt=LocalDateTime.now();r.updatedAt=LocalDateTime.now();requests.updateById(r);var p=players.selectById(player);p.workStatus="BUSY";p.updatedAt=LocalDateTime.now();players.updateById(p);}
 private String no(){return "EXC"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+UUID.randomUUID().toString().replace("-","").substring(0,6).toUpperCase();}private String write(List<String> urls){try{return json.writeValueAsString(urls==null?List.of():urls.stream().filter(x->x!=null&&!x.isBlank()).limit(9).toList());}catch(JsonProcessingException e){throw new IllegalArgumentException("申请凭证保存失败");}}private Map<String,Object> view(Map<String,Object>r){var x=new LinkedHashMap<>(r);Object proof=r.get("proof_urls");if(proof!=null)try{x.put("proofUrls",json.readValue(proof.toString(),List.class));}catch(Exception ignored){x.put("proofUrls",List.of());}return x;}public record Command(String requestType,Long sourceOrderMemberId,Long targetPlayerId,String reason,List<String>proofUrls){}
}
